export function translateStatus(value, lang) {
  if (lang === 'tr' || !value) return value;
  return STATUS_TR[value]?.[lang] || value;
}

export function translateCategory(value, lang) {
  if (lang === 'tr' || !value) return value;
  return CATEGORY_TR[value]?.[lang] || value;
}

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [lang, setLang] = useState(localStorage.getItem('envanter_lang') || 'tr');

  function changeLang(l) {
    localStorage.setItem('envanter_lang', l);
    setLang(l);
  }

  function t(key) {
    return DICT[key]?.[lang] || DICT[key]?.tr || key;
  }

  return (
    <LanguageContext.Provider value={{ lang, setLang: changeLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLang() {
  return useContext(LanguageContext);
}
